package app.stella.reader;
import android.app.*;
import android.os.*;
import android.content.*;
import android.net.Uri;
import android.webkit.*;
import android.view.*;
import android.widget.Toast;
import android.speech.tts.*;
import android.media.*;
import org.json.*;
import java.io.*;
import java.net.*;
