public class MainActivity extends Activity {
 WebView web; ReaderStore store; EdgeSpeech edge; ServerSocket server; String origin; boolean pageReady=false;Uri pendingUri; final ExecutorService workers=Executors.newCachedThreadPool();
 final Map<String,TextToSpeech> engines=new ConcurrentHashMap<>();final Map<String,String> labels=new HashMap<>();final Set<String> ready=new CopyOnWriteArraySet<>();TextToSpeech current;String defaultEngine="";int speechGen=0;AudioManager audioManager;AudioFocusRequest focus;
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(0xff102d32);getWindow().setNavigationBarColor(0xff102d32);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);
  if(Build.VERSION.SDK_INT>=35)getWindow().getDecorView().setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets i=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(i.left,i.top,i.right,i.bottom);return insets;});
  web=new WebView(this);setContentView(web);web.setBackgroundColor(0xff102d32);WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setMediaPlaybackRequiresUserGesture(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);web.addJavascriptInterface(new Bridge(),"AndroidBridge");
  web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){if(r.getUrl().toString().startsWith(origin+"/"))return false;if(r.isForMainFrame()&&Arrays.asList("http","https","mailto").contains(r.getUrl().getScheme()))try{startActivity(new Intent(Intent.ACTION_VIEW,r.getUrl()));}catch(Exception ignored){}return true;}@Override public void onPageFinished(WebView w,String url){if(url.equals(origin+"/")){pageReady=true;if(pendingUri!=null){Uri u=pendingUri;pendingUri=null;importUri(u);}}}});
  web.setWebChromeClient(new WebChromeClient(){@Override public boolean onConsoleMessage(ConsoleMessage m){android.util.Log.d("StellaWeb",m.message());return true;}});
  audioManager=(AudioManager)getSystemService(AUDIO_SERVICE);focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN_TRANSIENT_MAY_DUCK).setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build()).setOnAudioFocusChangeListener(change->{if(change<0)pauseNative();}).build();
  try{store=new ReaderStore(this);edge=new EdgeSpeech(new File(getFilesDir(),"edge-voices.json"));try{edge.seed(getAssets().open("web/data/edge-voices.json"));}catch(Exception ignored){}workers.execute(()->{try{edge.refresh();emit("stella-voices-refresh",new JSONObject());}catch(Exception ignored){}});server=new ServerSocket(18789,8,InetAddress.getByName("127.0.0.1"));origin="http://127.0.0.1:"+server.getLocalPort();Thread accept=new Thread(()->{while(!server.isClosed())try{Socket s=server.accept();workers.execute(()->serve(s));}catch(Exception ignored){}});accept.setDaemon(true);accept.start();web.loadUrl(origin+"/");}catch(Exception e){new AlertDialog.Builder(this).setTitle("Stella 启动失败").setMessage(e.getMessage()+"\n书库数据已保留，请重新打开。").setPositiveButton("关闭",(d,w)->finish()).show();return;}
  initVoices();if(getIntent().getData()!=null)pendingUri=getIntent().getData();
 }
 void initVoices(){final TextToSpeech[] first=new TextToSpeech[1];first[0]=new TextToSpeech(this,status->{if(status==TextToSpeech.SUCCESS){TextToSpeech t=first[0];defaultEngine=t.getDefaultEngine();engines.put(defaultEngine,t);ready.add(defaultEngine);for(TextToSpeech.EngineInfo e:t.getEngines()){labels.put(e.name,e.label);if(!engines.containsKey(e.name)){final String name=e.name;final TextToSpeech[] holder=new TextToSpeech[1];holder[0]=new TextToSpeech(this,s->{if(s==TextToSpeech.SUCCESS){ready.add(name);configure(holder[0]);emit("stella-voices-refresh",new JSONObject());}},name);engines.put(name,holder[0]);}}configure(t);emit("stella-voices-refresh",new JSONObject());}});}
 void configure(TextToSpeech t){t.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build());t.setOnUtteranceProgressListener(new UtteranceProgressListener(){public void onStart(String id){}public void onDone(String id){speechEvent(id,"done");}public void onError(String id){speechEvent(id,"error");}});}
 void speechEvent(String id,String status){try{emit("stella-speech",new JSONObject().put("gen",Integer.parseInt(id)).put("status",status));}catch(Exception ignored){}}
 synchronized JSONArray voices(){JSONArray a=new JSONArray();for(String e:new ArrayList<>(ready))try{TextToSpeech t=engines.get(e);Set<Voice> voices=t.getVoices();if(voices==null)continue;for(Voice v:voices){if(v.getFeatures().contains(TextToSpeech.Engine.KEY_FEATURE_NOT_INSTALLED))continue;a.put(new JSONObject().put("voiceURI","native:"+e+":"+v.getName()).put("name",labels.getOrDefault(e,e)+" · "+v.getName()+(v.isNetworkConnectionRequired()?"（联网）":"（离线）")).put("lang",v.getLocale().toLanguageTag()).put("source","native").put("networkRequired",v.isNetworkConnectionRequired()));}}catch(Exception ignored){}return a;}
 void emit(String name,JSONObject data){runOnUiThread(()->{if(web!=null)web.evaluateJavascript("window.dispatchEvent(new CustomEvent("+JSONObject.quote(name)+",{detail:"+data.toString()+"}));",null);});}
 void notifyError(String text){runOnUiThread(()->Toast.makeText(this,text,Toast.LENGTH_LONG).show());}
 void pauseNative(){if(current!=null&&current.isSpeaking()){current.stop();speechEvent(String.valueOf(speechGen),"paused");}}
 public final class Bridge {
  @JavascriptInterface public void pickBook(){runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/epub+zip","application/octet-stream","application/zip"});startActivityForResult(i,100);});}
  @JavascriptInterface public void speak(String text,String uri,float rate,int gen){runOnUiThread(()->{speechGen=gen;String engine=defaultEngine,name="";if(uri.startsWith("native:")){String[] p=uri.split(":",3);if(p.length==3){engine=p[1];name=p[2];}}TextToSpeech t=engines.get(engine);if(t==null||!ready.contains(engine)){speechEvent(String.valueOf(gen),"error");return;}current=t;if(!name.isEmpty()){boolean found=false;for(Voice v:t.getVoices())if(v.getName().equals(name)){t.setVoice(v);found=true;break;}if(!found){speechEvent(String.valueOf(gen),"error");return;}}else t.setLanguage(Locale.SIMPLIFIED_CHINESE);t.setSpeechRate(Math.max(.6f,Math.min(2f,rate)));audioManager.requestAudioFocus(focus);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);int result=t.speak(text,TextToSpeech.QUEUE_FLUSH,new Bundle(),String.valueOf(gen));if(result==TextToSpeech.ERROR)speechEvent(String.valueOf(gen),"error");});}
  @JavascriptInterface public void stopSpeech(){runOnUiThread(()->{for(TextToSpeech t:engines.values())t.stop();getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);});}
  @JavascriptInterface public void voiceSettings(){runOnUiThread(()->{try{startActivity(new Intent("com.android.settings.TTS_SETTINGS"));}catch(Exception e){startActivity(new Intent(android.provider.Settings.ACTION_SETTINGS));}});}
  @JavascriptInterface public void background(){runOnUiThread(()->moveTaskToBack(true));}
  @JavascriptInterface public void downloadBook(String url,String token,String id){workers.execute(()->{try{URL base=new URL(url);if(!base.getProtocol().equals("http")||!base.getHost().matches("(192\\.168\\..*|10\\..*|172\\.(1[6-9]|2[0-9]|3[01])\\..*)")||!id.matches("[a-zA-Z0-9_-]+"))throw new IOException("仅支持已配对局域网电脑");HttpURLConnection c=(HttpURLConnection)new URL(url+"/book/"+id).openConnection();c.setConnectTimeout(10000);c.setReadTimeout(60000);c.setRequestProperty("Authorization","Bearer "+token);c.setInstanceFollowRedirects(false);try{if(c.getResponseCode()!=200)throw new IOException("电脑书籍下载失败，请重新配对");JSONObject b=store.importStream(c.getInputStream());emit("stella-library-downloaded",new JSONObject().put("id",b.getString("id")));notifyError("已复制 EPUB 到手机，电脑原书保留");}finally{c.disconnect();}}catch(Exception e){notifyError("复制失败："+e.getMessage());try{emit("stella-download-error",new JSONObject().put("id",id).put("message",e.getMessage()));}catch(Exception ignored){}}});}
 }
 void importUri(Uri uri){workers.execute(()->{try{JSONObject b=store.importStream(getContentResolver().openInputStream(uri));emit("stella-imported",new JSONObject().put("id",b.getString("id")));notifyError("已导入《"+b.getString("title")+"》");}catch(Exception e){notifyError("导入失败："+e.getMessage());}});}
 @Override protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(r==100&&result==RESULT_OK&&data!=null&&data.getData()!=null)importUri(data.getData());}
 @Override protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);if(i.getData()!=null){if(pageReady)importUri(i.getData());else pendingUri=i.getData();}}
 @Override public void onBackPressed(){emit("stella-back",new JSONObject());}
 @Override protected void onPause(){pauseNative();if(web!=null)web.evaluateJavascript("document.dispatchEvent(new Event('visibilitychange'));",null);super.onPause();}
 @Override protected void onDestroy(){for(TextToSpeech t:engines.values())t.shutdown();if(audioManager!=null&&focus!=null)audioManager.abandonAudioFocusRequest(focus);try{if(server!=null)server.close();}catch(Exception ignored){}workers.shutdownNow();if(web!=null){web.destroy();web=null;}super.onDestroy();}
 static String line(InputStream in)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();int c;while((c=in.read())!=-1){if(c=='\n')break;if(c!='\r')out.write(c);if(out.size()>16384)throw new IOException("请求头过大");}return out.toString("UTF-8");}
 static String mime(String p){p=p.toLowerCase(Locale.ROOT);if(p.endsWith(".xhtml"))return "application/xhtml+xml; charset=utf-8";if(p.endsWith(".html")||p.endsWith(".htm"))return "text/html; charset=utf-8";if(p.endsWith(".js"))return "text/javascript; charset=utf-8";if(p.endsWith(".css"))return "text/css; charset=utf-8";if(p.endsWith(".svg"))return "image/svg+xml";if(p.endsWith(".png"))return "image/png";if(p.endsWith(".jpg")||p.endsWith(".jpeg"))return "image/jpeg";if(p.endsWith(".woff2"))return "font/woff2";if(p.endsWith(".woff"))return "font/woff";if(p.endsWith(".ttf"))return "font/ttf";if(p.endsWith(".gif"))return "image/gif";return "application/octet-stream";}
 void serve(Socket socket){try(Socket s=socket){s.setSoTimeout(60000);InputStream in=new BufferedInputStream(s.getInputStream());String first=line(in);String[] parts=first.split(" ");if(parts.length<2)return;String method=parts[0],raw=parts[1],h;int length=0;String host="",requestOrigin="";while(!(h=line(in)).isEmpty()){int k=h.indexOf(':');if(k>0){String key=h.substring(0,k).toLowerCase(Locale.ROOT),val=h.substring(k+1).trim();if(key.equals("content-length"))length=Integer.parseInt(val);if(key.equals("host"))host=val;if(key.equals("origin"))requestOrigin=val;}}
  if(!host.equals("127.0.0.1:"+server.getLocalPort())||(!requestOrigin.isEmpty()&&!requestOrigin.equals(origin))){respond(s,403,"text/plain","Forbidden".getBytes("UTF-8"),false);return;}
  if(length<0||length>180*1024*1024)throw new IOException("请求体过大");byte[] body=new byte[length];int offset=0,n;while(offset<length&&(n=in.read(body,offset,length-offset))!=-1)offset+=n;if(offset!=length)throw new IOException("请求不完整");String p=URLDecoder.decode(raw.split("\\?",2)[0].replace("+","%2B"),"UTF-8");byte[] result;String type="application/json; charset=utf-8";boolean bookResource=false;
  try{
   if(p.equals("/api/voices")){String warning="";if(raw.contains("refresh=1"))try{edge.refresh();}catch(Exception e){warning="在线列表刷新失败，保留已有音色："+e.getMessage();}JSONArray all=voices(),online=edge.cachedVoices();for(int i=0;i<online.length();i++)all.put(online.getJSONObject(i));File catalog=new File(getFilesDir(),"desktop-voice-catalog.json");if(catalog.exists())try{JSONArray imported=new JSONObject(new String(ReaderStore.read(new FileInputStream(catalog),2*1024*1024),"UTF-8")).getJSONArray("voices");for(int i=0;i<imported.length();i++)all.put(imported.getJSONObject(i));}catch(Exception ignored){}result=new JSONObject().put("voices",all).put("warning",warning).put("directOnlineCount",online.length()).toString().getBytes("UTF-8");}
   else if(p.equals("/api/voice-catalog/import")&&method.equals("POST")){JSONObject d=new JSONObject(new String(body,"UTF-8"));JSONArray imported=d.getJSONArray("voices"),clean=new JSONArray();if(imported.length()>2000)throw new IOException("音色目录过大");for(int i=0;i<imported.length();i++){JSONObject v=imported.getJSONObject(i);String uri=v.getString("voiceURI");if(uri.length()>300||!uri.matches("^(edge|pc|azure|openai):.+"))continue;clean.put(new JSONObject().put("voiceURI",uri).put("name",v.optString("name",uri)).put("lang",v.optString("lang","")).put("source",uri.startsWith("edge:")?"edge-direct":"desktop-linked"));}File catalog=new File(getFilesDir(),"desktop-voice-catalog.json");try(FileOutputStream output=new FileOutputStream(catalog)){output.write(new JSONObject().put("voices",clean).toString().getBytes("UTF-8"));}result=new JSONObject().put("ok",true).put("count",clean.length()).toString().getBytes("UTF-8");}
   else if(p.equals("/api/tts")&&method.equals("POST")){JSONObject d=new JSONObject(new String(body,"UTF-8"));if(!d.optString("voice").startsWith("edge:"))throw new IOException("该电脑专用声音需要连接电脑，请切换手机在线音色");result=edge.synthesize(d.getString("text"),d.getString("voice"),d.optDouble("rate",1));type="audio/mpeg";}
   else if(p.startsWith("/api/books/")&&(p.contains("/res/")||p.endsWith("/cover"))){String[] a=p.split("/",6);String resource=a.length==6?a[5]:null;result=store.resource(a[3],resource);type=resource!=null?mime(resource):mime(store.meta(a[3]).getString("coverHref"));bookResource=true;}
   else if(p.startsWith("/api/")){JSONObject d=length>0?new JSONObject(new String(body,"UTF-8")):new JSONObject();result=store.request(method,raw,d).toString().getBytes("UTF-8");}
   else{String asset=p.equals("/")?"web/index.html":p.startsWith("/web/")?p.substring(1):"web"+p;if(asset.contains(".."))throw new IOException("路径无效");result=ReaderStore.read(getAssets().open(asset),32*1024*1024);type=mime(asset);}
   respond(s,200,type,result,bookResource);
  }catch(Exception e){respond(s,400,"application/json; charset=utf-8",new JSONObject().put("error",new JSONObject().put("message",e.getMessage()==null?"操作失败":e.getMessage()).put("code","ANDROID_ERROR")).toString().getBytes("UTF-8"),false);}
 }catch(Exception e){android.util.Log.w("StellaServer",String.valueOf(e));}}
 void respond(Socket s,int status,String type,byte[] bytes,boolean book)throws IOException{OutputStream out=s.getOutputStream();String header="HTTP/1.1 "+status+" OK\r\nContent-Type: "+type+"\r\nContent-Length: "+bytes.length+"\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\nConnection: close\r\n";if(book)header+="Content-Security-Policy: default-src 'self' data: blob:; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; script-src 'none'\r\n";out.write((header+"\r\n").getBytes("UTF-8"));out.write(bytes);out.flush();}
}
